HARD = {"failed", "timeout", "skipped_blind", "skipped_paywall"}
WHY = {
  "failed": "эксперт упал",
  "timeout": "не уложился в срок",
  "skipped_blind": "нечего смотреть: граф не дал нужного",
  "skipped_paywall": "недоступно на текущем тарифе",
}
gaps = {}
for r in ctx.get("expert_runs", []):
    if r["status"] not in HARD: continue
    gaps.setdefault(r["direction"], []).append({
      "эксперт": r["role"], "почему": WHY[r["status"]], "детали": r.get("error", "")[:200],
    })
coverage = {}
for d in ctx.get("selected", []):
    lost = gaps.get(d, [])
    total = sum(1 for r in ctx.get("expert_runs", []) if r["direction"] == d)
    coverage[d] = {
      "полная": not lost,
      "проверено": total - len(lost), "из": total,
      "не проверено": lost,
    }
# динамика: полнота меряется не экспертами, а очередью охоты — что осталось в hunt_queue, то не досмотрено (обычно кончился бюджет проб)
hunt = ctx.get("hunt")
if hunt is not None:
    left = ctx.get("hunt_queue", [])
    planned = hunt.get("planned", len(left))
    blinded = hunt.get("blinded", [])
    coverage["динамика"] = {
      "полная": not left and not blinded,
      "проверено": planned - len(left), "из": planned,
      "не проверено": [{"цель": r["target"], "класс": r["class"]} for r in left[:50]],
      "ослеплено WAF": [{"цель": b["target"], "класс": b["class"]} for b in blinded[:50]],
      "бюджет исчерпан": hunt.get("probes_left", 1) <= 0,
      "WAF": (ctx.get("waf") or {}).get("present", False),
    }
# ponytail: одно правило вместо флага на каждом отчёте — направление с дыркой никогда не «чисто»
ctx["coverage"] = coverage
ctx["has_gaps"] = any(not c["полная"] for c in coverage.values())

