import json
raw = DAST_AUTH.strip()
sess = {"enabled": False, "primary": None, "by_label": {}, "identities": []}
def login(it):
    if it.get("token"): return {"type": "bearer", "value": it["token"]}
    if it.get("cookie"): return {"type": "cookie", "value": it["cookie"]}
    lg = it.get("login")
    if not lg: return None
    r = http({"method": lg.get("method", "POST"), "url": lg["url"], "headers": lg.get("headers", {}), "body": lg.get("body", "")})
    sc = r.headers.get("set-cookie")
    if sc: return {"type": "cookie", "value": sc}
    try: body = json.loads(r.body)
    except Exception: body = {}
    tok = body
    for k in str(lg.get("token_path", "token")).split("."):
        tok = tok.get(k) if isinstance(tok, dict) else None
    return {"type": "bearer", "value": tok} if tok else None
for it in (json.loads(raw) if raw else []):
    auth = login(it)
    if not auth: continue
    label = it.get("label") or ("id%d" % (len(sess["identities"]) + 1))
    self_id = None
    slf = it.get("self")
    if slf:
        rs = http({"method": "GET", "url": slf["url"]}, session=auth)
        try: b = json.loads(rs.body)
        except Exception: b = {}
        self_id = b.get(slf.get("field", "id")) if isinstance(b, dict) else None
    sess["by_label"][label] = auth
    sess["identities"].append({"label": label, "self_id": self_id, "alive": True})
if sess["identities"]:
    sess["enabled"] = True
    sess["primary"] = sess["by_label"][sess["identities"][0]["label"]]
ctx["sessions"] = sess
print(json.dumps({"enabled": sess["enabled"], "identities": sess["identities"]}, ensure_ascii=False))

m = ctx["dast_map"]
targets = []
for p in m["map"]:
    for f in p.get("forms", []):
        targets.append({"kind": "form", "url": p["url"], "inputs": f.get("fields", [])})
    for q in p.get("params", []):
        targets.append({"kind": "param", "url": p["url"], "name": q})
# входы глубже ссылок (content-discovery): не-связанные пути и объявленные приложением
for e in ctx.get("dast_discovered", {}).get("endpoints", []):
    targets.append({"kind": "endpoint", "url": e["url"], "found": e.get("source")})
ctx["dast_targets"] = {"count": len(targets), "items": targets, "pages": m["pages"], "discovered": ctx.get("dast_discovered", {}).get("count", 0)}

import json
eps = ctx["dast_targets"]["items"]
SENS = tuple(SENSITIVE.split(","))
def shape(body, ctype):
    if "json" not in (ctype or "").lower(): return None
    try: v = json.loads(body)
    except Exception: return None
    rows = v if isinstance(v, list) else [v]
    obj = next((r for r in rows if isinstance(r, dict)), None)
    if obj is None: return None
    fields = sorted(obj.keys())
    return {"kind": "collection" if isinstance(v, list) else "object", "count": len(rows), "fields": fields,
            "ids": [f for f in fields if f.lower().endswith(("id","_id","uuid","ref","key"))],
            "sensitive": [f for f in fields if any(s in f.lower() for s in SENS)]}
shapes, seeds = [], []
sess = (ctx.get("sessions") or {}).get("primary")   # наблюдаем за-логиновые ответы: там id-поля и чувствительное
for t in eps:
    r = http({"method": "GET", "url": t["url"]}, session=sess, rate=ctx.get("rate"))   # только наблюдение, без изменений
    sh = shape(r.body[:int(MARK)], r.headers.get("content-type"))
    if not sh: continue
    shapes.append({"endpoint": t["url"], "status": r.status, **sh})
    if sh["ids"]: seeds.append({"target": t, "class": "access", "why": "id-поля: " + ",".join(sh["ids"])})
    if sh["sensitive"]: seeds.append({"target": t, "class": "disclosure", "why": "поля: " + ",".join(sh["sensitive"])})
graph_annotate("DataShape", shapes, project=ctx["project_id"])   # DataShape-узлы и RETURNS-рёбра в ту же карту
ctx["dast_shapes"] = {"observed": len(shapes), "shapes": shapes, "seeds": seeds}
print(json.dumps({"observed": len(shapes), "access": sum(1 for s in seeds if s["class"] == "access"), "disclosure": sum(1 for s in seeds if s["class"] == "disclosure")}, ensure_ascii=False))

