import json, time, secrets
h = ctx.get("hypothesis", {})
if h.get("give_up"):
    print(json.dumps({"skipped": "give_up"}, ensure_ascii=False)); raise SystemExit
c = ctx.get("canary", {})
probe = h.get("probe", {})
blob = " ".join([probe.get("url", ""), probe.get("body", "") or ""] + [str(x) for x in (probe.get("headers") or {}).values()])
oob_used = "%%OOB%%" in blob
token = ""
if oob_used:
    if not c.get("enabled"):
        print(json.dumps({"skipped": "no_canary"}, ensure_ascii=False)); raise SystemExit
    token = secrets.token_hex(8)                    # уникальный токен -> адрес канарейки
    host = token + "." + c["domain"]
    def sub(s): return s.replace("%%OOB%%", host) if isinstance(s, str) else s
    probe["url"] = sub(probe.get("url", ""))
    probe["body"] = sub(probe.get("body", "") or "")
    probe["headers"] = {k: sub(v) for k, v in (probe.get("headers") or {}).items()}
    ctx["canary"]["tokens"][token] = {"target": (ctx.get("current") or {}).get("target"), "class": (ctx.get("current") or {}).get("class")}
if not in_scope(probe["url"], ctx["dast_scope"]["allow"]):   # за охват не выходим
    print(json.dumps({"error": "out_of_scope"}, ensure_ascii=False)); raise SystemExit
sessions = ctx.get("sessions") or {}
def pick(label):
    return (sessions.get("by_label") or {}).get(label) or sessions.get("primary")
def send(req):
    t = time.time()
    r = http(req, session=pick(req.get("as")), rate=ctx.get("rate"))   # шлём от выбранной личности (access: от A по объекту B)
    return {"status": r.status, "ms": round((time.time() - t) * 1000, 3), "len": len(r.body), "body": r.body[:int(MARK)]}
a1 = send(probe); a2 = send(probe)                 # дважды — проверка воспроизводимости
base = send(h["control"]) if h.get("control") else None
waf = ctx.get("waf") or {}
blocked = bool(waf.get("present")) and (a1["status"] == waf.get("block_status") or any(m in (a1.get("body") or "").lower() for m in waf.get("block_markers", [])))   # WAF срезал — не «чисто»
oob = {"used": oob_used, "token": token, "hit": False}
if oob_used:                                       # подтверждение блайнда — не в ответе, а прилётом на канарейку
    end = time.time() + float(c.get("wait_s", 8))
    while time.time() < end:
        rp = http({"method": "GET", "url": c["poll"] + "?token=" + token}, rate=ctx.get("rate"))
        try: hits = json.loads(rp.body)
        except Exception: hits = []
        if hits:
            oob.update({"hit": True, "protocol": hits[0].get("protocol"), "at": hits[0].get("at"), "source": hits[0].get("remote")})
            break
        time.sleep(1)
print(json.dumps({
  "probe": a1, "probe_repeat": a2, "control": base,
  "diff_len": (a1["len"] - base["len"]) if base else None,
  "reproducible": a1["status"] == a2["status"],
  "oob": oob,
  "blocked": blocked,
}, ensure_ascii=False))

